  name: 'IconButtonFA4',
};
</script>

<style>
.btn {
  background-color: #007bff;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
}
.btn i {
  margin-right: 8px;
}
</style>
<!-- Icon button implementation complete. -->
```

### Script 2: Using Font Awesome 5 Syntax

First, ensure you have included Font Awesome 5 in your project, typically by adding the following line to your HTML file:
```html
<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/css/all.min.css">
```

Now, here is the Vue.js component script:

```html
