  <button class="btn">
    <i class="fas fa-thumbs-up"></i> Like
  </button>
</template>

<script>
export default {
  name: 'IconButtonFA5',
};
</script>

<style>
.btn {
  background-color: #007bff;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
}
.btn i {
  margin-right: 8px;
}
</style>
<!-- Icon button implementation complete. -->
```

